-- Initial reference data for gun_reference / plant_reference.
--
-- Source: Wikidata (structured claims, CC0) + English Wikipedia (infobox
-- wikitext + summary extract, CC BY-SA 4.0 — attribution required on reuse,
-- see each row's image_attribution/license columns) via
-- scripts/reference-data/import-reference-data.mjs, fetched live at import
-- time (not hand-written). Provenance is per-row (source/source_url/license
-- columns); import date for this batch is 2026-09-17.
--
-- Coverage is intentionally uneven — a field left null means neither source
-- had a verifiable value for it, not that one was omitted by mistake (e.g.
-- "AR-15" resolved to the general style/category article rather than one
-- specific product, so most spec fields are genuinely inapplicable there;
-- edibility/toxicity for plants is always null because no source checked
-- during research carries a verified structured field for it — see
-- scripts/reference-data/import-reference-data.mjs's header comment).
--
-- To add more entries later: extend GUN_SEEDS/PLANT_SEEDS in that script,
-- re-run it, and apply the output as a new migration the same way as this one.

insert into gun_reference (name, manufacturer, model, action_type, caliber, capacity, barrel_length, overall_length, weight, country, production_years, description, image_url, image_attribution, source, source_url, license)
values
  ('Glock 17', 'Glock Ges.m.b.H.', null, null, null, null, null, null, '710 g', 'Austria', '1980', 'Glock is a brand of polymer-framed, short-recoil-operated, locked-breech semi-automatic pistols designed and produced by Austrian manufacturer Glock GmbH. The firearm, designed by company founder Gaston Glock (1929–2023), entered Austrian military and police service in 1982 as the P80 after outperforming established competitors in reliability and safety tests. Despite initial market resistance due to its "plastic" construction, the Glock became the first commercially successful line of pistols with a polymer frame.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2017%20(6825676904).jpg', 'Askild Antonsen, CC BY 2.0 — via Wikimedia Commons (Glock 17 (6825676904).jpg)', 'Wikidata (Q172172) + Wikipedia ("Glock 17")', 'https://en.wikipedia.org/wiki/Glock%2017', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('AK-47', 'Fabryka Broni Radom, Kalashnikov Concern, Norinco, and Zastava Arms', null, 'Gas-operated, long-stroke piston, closed rotating bolt', '7.62×39mm', null, 'Overall length:; 415 mm; Rifled bore length:; 369 mm', 'Fixed wooden stock:; 880 mm; 875 mm (folding stock extended); 645 mm (stock folded)', 'Without magazine:; 3.47 kg; Magazine, empty:; 0.43 kg (early issue); 0.33 kg (steel); 0.25 kg (plastic); 0.17 kg (light alloy)', 'Soviet Union', '1948–present', 'The AK-47, full name Avtomat Kalashnikova 1947, officially known as the Avtomat Kalashnikova, is an assault rifle chambered for the 7.62×39mm cartridge. Developed in the Soviet Union by Russian small-arms designer Mikhail Kalashnikov, it is the originating firearm of the Kalashnikov family of rifles. After more than seven decades since its creation, the AK-47 model and its variants remain one of the most popular and widely used firearms in the world.', 'https://commons.wikimedia.org/wiki/Special:FilePath/AK-47%20type%20II%20noBG.png', 'User:Nemo5576, CC BY-SA 4.0 — via Wikimedia Commons (AK-47 type II noBG.png)', 'Wikidata (Q37116) + Wikipedia ("AK-47")', 'https://en.wikipedia.org/wiki/AK-47', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('AR-15–style rifle', 'ArmaLite', null, null, null, null, null, null, null, 'United States', null, 'An AR-15–style rifle is a lightweight semi-automatic rifle based on or similar to the Colt AR-15 design. The Colt model removed the selective fire feature of its predecessor, the original ArmaLite AR-15, which is a scaled-down derivative of the AR-10 design. It is closely related to the military M16 rifle.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stag2wi%20.jpg', 'TheAlphaWolf, Public domain — via Wikimedia Commons (Stag2wi .jpg)', 'Wikidata (Q6889079) + Wikipedia ("AR-15–style rifle")', 'https://en.wikipedia.org/wiki/AR-15%E2%80%93style%20rifle', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Beretta 92', 'Beretta', null, 'Short recoil, hinged locking piece assisted breechblock', '9×19mm Parabellum (92 series); .380 ACP (92 series); .40 S&W (96 series); 9×21mm IMI (98 series); 7.65mm Luger (98 series)', null, '125 mm; 119 mm (Vertec/Elites/Border Marshal/Combo); 109 mm (Compact/Centurion)', '217 mm; 211 mm (Vertec); 197 mm (Compact/Centurion)', '950 g (92); 970 g (92S/SB/F/G); 920 g (92D); 900 g (Compact/Vertec)', 'Italy', '1976–present', 'The Beretta 92 is a series of semi-automatic pistols designed and manufactured by Beretta of Italy.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Beretta%2092S%20(cropped).jpg', 'U.S. Bureau of Alcohol, Tobacco, Firearms and Explosives, Public domain — via Wikimedia Commons (Beretta 92S (cropped).jpg)', 'Wikidata (Q211333) + Wikipedia ("Beretta 92")', 'https://en.wikipedia.org/wiki/Beretta%2092', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Remington Model 700', 'Remington Arms', null, 'Bolt action, rotating bolt with 2 lugs', '6mm Remington; 6.5mm Creedmoor; 6.5×47mm Lapua; 7mm-08 Remington; 7mm Remington Magnum; 7mm Shooting Times Westerner; 8mm Remington Magnum; 8.6mm Blackout; .17 Remington Fireball; .220 Swift; .221 Remington Fireball; .222 Remington; .223 Remington; .22-250 Remington; .243 Winchester; .25-06 Remington; .257 Roberts; .257 Weatherby Magnum; .260 Remington; .270 Winchester; .280 Remington; .30-06 Springfield; .300 Remington Ultra Magnum; .300 Weatherby Magnum; .300 Winchester Magnum; .300 Winchester Short Magnum; .308 Winchester; .338 Lapua Magnum; .416 Remington Magnum; .458 Winchester Magnum', null, null, '41.5 in', '8.99 lb', 'United States', '1962–present', 'The Remington Model 700 is part of a series of bolt-action centerfire rifles manufactured by Remington Arms since 1962. It is a progressive variant of the Remington Model 721 and Model 722 rifles series, which was introduced in 1948. The M24 and M40 military sniper rifles, which are both based on the Model 700 design, are in use by the United States Army and United States Marine Corps, respectively.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hunting%20rifle%2002.png', 'Ragnhild Kjeldsen, CC BY-SA 4.0 — via Wikimedia Commons (Hunting rifle 02.png)', 'Wikidata (Q857562) + Wikipedia ("Remington Model 700")', 'https://en.wikipedia.org/wiki/Remington%20Model%20700', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Colt M1911', 'Colt Manufacturing Company, Smith & Wesson, Norinco, other companies', null, 'Short recoil operation', '.45 ACP, .455 Webley Auto (British Contract), .38 Super, 9x19mm Parabellum, 7.65mm Parabellum, 9mm Steyr, .400 Corbon, others', null, null, '8.5 in (216 mm)', '39 oz empty, with magazine', 'United States', '1911–present', 'The Colt M1911 is a single-action, recoil-operated, semi-automatic pistol chambered primarily for the .45 ACP cartridge.', 'https://commons.wikimedia.org/wiki/Special:FilePath/M1911A1.png', 'M62, CC BY-SA 3.0 — via Wikimedia Commons (M1911A1.png)', 'Wikidata (Q201419) + Wikipedia ("M1911 pistol")', 'https://en.wikipedia.org/wiki/M1911%20pistol', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.');

insert into plant_reference (common_name, other_common_names, scientific_name, family, habitat, season, identification_notes, description, edibility, toxicity_notes, image_url, image_attribution, source, source_url, license)
values
  ('Stinging nettle', null, 'Urtica dioica', 'Urticaceae', null, null, null, 'Urtica dioica, often known as common nettle, burn nettle, stinging nettle, nettle leaf, or just a nettle or stinger, is a herbaceous perennial flowering plant in the family Urticaceae. Originally native to Europe, much of temperate Asia and western North Africa, it is now found worldwide.', null, null, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brennnessel%201.JPG', 'CC BY-SA 3.0 — via Wikimedia Commons (Brennnessel 1.JPG)', 'Wikidata (Q155909) + Wikipedia ("Urtica dioica")', 'https://en.wikipedia.org/wiki/Urtica%20dioica', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Dandelion', null, 'Taraxacum', 'Asteraceae', null, null, null, 'Taraxacum is a genus of flowering plants in the family Asteraceae which consists of species commonly known as dandelions. The scientific and hobby study of the genus is known as taraxacology. The genus has a near-cosmopolitan distribution, absent only from tropical and polar areas. Two of the most common species worldwide, T. officinale and T. erythrospermum, are European species introduced into North America, where they are non native. Dandelions thrive in temperate regions and can be found in yards, gardens, sides of roads, among crops, and in many other habitats.', null, null, 'https://commons.wikimedia.org/wiki/Special:FilePath/DandelionFlower.jpg', 'Greg Hume, CC BY-SA 3.0 — via Wikimedia Commons (DandelionFlower.jpg)', 'Wikidata (Q30024) + Wikipedia ("Taraxacum")', 'https://en.wikipedia.org/wiki/Taraxacum', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Elder', null, 'Sambucus nigra', 'Viburnaceae', null, null, null, 'Sambucus nigra is a temperate species of tree or shrub in the family Viburnaceae native to the Azores, Europe, and the Middle East. Common names include elder, elderberry, black elder, European elder,  European elderberry, and European black elderberry. It grows in a variety of conditions including both wet and dry fertile soils, primarily in sunny locations. The plant is widely grown as an ornamental shrub or small tree.', null, null, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sambucus%20nigra%20004.jpg', 'Willow, CC BY 2.5 — via Wikimedia Commons (Sambucus nigra 004.jpg)', 'Wikidata (Q22701) + Wikipedia ("Sambucus nigra")', 'https://en.wikipedia.org/wiki/Sambucus%20nigra', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Wild garlic', null, 'Allium ursinum', 'Amaryllidaceae', null, null, null, 'Allium ursinum, known as wild garlic, ramsons, cowleekes, cows''s leek, cowleek, buckrams, broad-leaved garlic, wood garlic, bear leek, Eurasian wild garlic, onion grass, or bear''s garlic, is a bulbous perennial flowering plant in the amaryllis family, Amaryllidaceae. It is native to Eurasia, where it grows in moist woodland. It is a wild relative of onion and garlic, all belonging to the same genus, Allium. There are two recognized subspecies: A. ursinum subsp. ursinum and A. ursinum subsp. ucrainicum.', null, null, 'https://commons.wikimedia.org/wiki/Special:FilePath/Daslook%20(Allium%20ursinum)%2007-04-2020.%20(actm.)%2004.jpg', 'Agnes Monkelbaan, CC BY-SA 4.0 — via Wikimedia Commons (Daslook (Allium ursinum) 07-04-2020. (actm.) 04.jpg)', 'Wikidata (Q130882) + Wikipedia ("Allium ursinum")', 'https://en.wikipedia.org/wiki/Allium%20ursinum', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.'),
  ('Hawthorn', null, 'Crataegus', 'Rosaceae', null, null, null, 'Crataegus, commonly called hawthorn, quickthorn, thornapple, May-tree, whitethorn, Mayflower or hawberry, is a genus of several hundred species of shrubs and trees in the family Rosaceae, native to temperate regions of the Northern Hemisphere in Europe, Asia, North Africa and North America. The name "hawthorn" was originally applied to the species native to northern Europe, especially the common hawthorn C. monogyna, and the unmodified name is often so used in Britain and Ireland. The name is now also applied to the entire genus and to the related Asian genus Rhaphiolepis.', null, null, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crataegus%2C%20various%20species%2C%20fruit.jpg', 'Nadiatalent, Public domain — via Wikimedia Commons (Crataegus, various species, fruit.jpg)', 'Wikidata (Q132557) + Wikipedia ("Crataegus")', 'https://en.wikipedia.org/wiki/Crataegus', 'Wikidata claims: CC0. Wikipedia text: CC BY-SA 4.0 (attribution required on reuse). Image: see image_attribution.');
